import os, pathlib, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); os.chdir(HERE)
APP = pathlib.Path(HERE).parent.joinpath('inkling.html').as_uri()
import asyncio, json
from playwright.async_api import async_playwright
FAKE = open('test13.py').read().split('FAKE = """')[1].split('"""')[0]
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await b.new_page(viewport={'width':1440,'height':900})
        errs=[]; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.route('**/three.min.js', lambda route: route.fulfill(path='fake_three.js', content_type='application/javascript'))
        await pg.add_init_script(open('mock3d.js').read() + FAKE)
        await pg.goto(APP); await pg.wait_for_timeout(900)
        await pg.click('#newNotebook'); await pg.fill('.modal input.field', 'K'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(300)
        await (await pg.query_selector_all('.kind'))[2].click(); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(600)
        await pg.click('.rtabs button:has-text("Insert")'); await pg.click('#ribbon button[aria-label^="Screen window"]'); await pg.wait_for_timeout(400)
        await pg.click('.obj-scr .scr-empty button:has-text("Choose a tab or window")'); await pg.wait_for_timeout(700)
        win = await pg.query_selector('.obj-scr'); bb = await win.bounding_box()
        px, py = bb['x']+bb['width']*0.7, bb['y']+bb['height']*0.7
        await pg.mouse.click(px, py, button='right'); await pg.wait_for_timeout(200)
        print('menu:', await pg.evaluate("[...document.querySelectorAll('.menu:not(.sub) > button,.menu:not(.sub) > .mlabel')].map(b=>b.innerText.trim())"))
        await pg.hover('.menu button:has-text("Recording")'); await pg.wait_for_timeout(350)
        print('recording sub-menu:', await pg.evaluate("[...document.querySelectorAll('.menu.sub button,.menu.sub .mlabel')].map(b=>b.innerText.trim())"))
        await pg.click('.menu:not(.sub) button:has-text("Add a note with an arrow")'); await pg.wait_for_timeout(300)
        await pg.keyboard.type('Look here'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(300)
        note = await pg.evaluate("(()=>{const n=document.querySelector('.wn-wrap .w3-note'); const a=document.querySelector('.wn-wrap .w3-ah'); const l=document.querySelector('.wn-wrap .w3-arrows line'); const r=a.getBoundingClientRect(); return {text: n.innerText.trim(), arrowTip: [Math.round(r.x+r.width/2), Math.round(r.y+r.height/2)], arrowDrawn: !!l}})()")
        print('note:', note, '| right-click point:', [round(px), round(py)])
        # zoom in and back
        await pg.mouse.move(bb['x']+bb['width']*0.3, bb['y']+bb['height']*0.5); await pg.mouse.wheel(0, -400); await pg.wait_for_timeout(200)
        print('zoomed:', await pg.evaluate("[document.querySelector('.obj-scr .w3-stage').style.transform.slice(0,40), document.querySelector('.obj-scr .w3-zoom').innerText]"))
        await pg.click('.obj-scr .w3-zoom'); await pg.wait_for_timeout(100)
        print('reset:', await pg.evaluate("document.querySelector('.obj-scr .w3-stage').style.transform === ''"))
        # record 3.5 s through the sub-menu
        await pg.mouse.click(bb['x']+40, bb['y']+bb['height']*0.5, button='right'); await pg.hover('.menu button:has-text("Recording")'); await pg.wait_for_timeout(350)
        await pg.click('.menu.sub button:has-text("Record (up to 5 minutes)")'); await pg.wait_for_timeout(3500)
        await pg.mouse.click(bb['x']+40, bb['y']+bb['height']*0.5, button='right'); await pg.hover('.menu button:has-text("Recording")'); await pg.wait_for_timeout(350)
        stop = await pg.evaluate("[...document.querySelectorAll('.menu.sub button')].map(b=>b.innerText)[0]"); print('stop item:', stop)
        await pg.click('.menu.sub button:has-text("Stop recording")'); await pg.wait_for_timeout(3000)
        await pg.click('#toast button'); await pg.wait_for_timeout(500)
        # time range on the note: 1.0 – 2.0 s
        nb = await (await pg.query_selector('.wn-wrap .w3-note')).bounding_box()
        await pg.mouse.click(nb['x']+10, nb['y']+8, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu button:has-text("When it shows")'); await pg.wait_for_timeout(200)
        ins = await pg.query_selector_all('.modal input[type=number]'); await ins[0].fill('1'); await ins[1].fill('2')
        await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(300)
        print('note badge:', await pg.inner_text('.wn-wrap .w3-ntime'))
        await pg.evaluate("(()=>{const v=[...document.querySelectorAll('.obj-scr video')].find(v=>!v.hidden&&v.src); v.loop=false; v.currentTime=0; v.play();})()")
        await pg.wait_for_timeout(400); a = await pg.evaluate("[...document.querySelectorAll('.obj-scr video')].find(v=>!v.hidden&&v.src).currentTime.toFixed(1) + 's hidden=' + document.querySelector('.wn-wrap .w3-note').classList.contains('off')")
        await pg.wait_for_timeout(1100); c = await pg.evaluate("[...document.querySelectorAll('.obj-scr video')].find(v=>!v.hidden&&v.src).currentTime.toFixed(1) + 's hidden=' + document.querySelector('.wn-wrap .w3-note').classList.contains('off')")
        await pg.wait_for_timeout(1200); d = await pg.evaluate("[...document.querySelectorAll('.obj-scr video')].find(v=>!v.hidden&&v.src).currentTime.toFixed(1) + 's hidden=' + document.querySelector('.wn-wrap .w3-note').classList.contains('off')")
        print('note during video:', a, '|', c, '|', d)
        # folder
        await pg.mouse.click(bb['x']+40, bb['y']+bb['height']*0.5, button='right'); await pg.hover('.menu button:has-text("Recording")'); await pg.wait_for_timeout(350)
        await pg.click('.menu.sub button:has-text("Recordings folder")'); await pg.wait_for_timeout(600)
        print('folder:', (await pg.inner_text('.modal')).replace('\n', ' | ')[:220])
        await pg.keyboard.press('Escape')
        # 3D window sub-menu
        await pg.click('#dock button[aria-label="3D studio"]'); await pg.wait_for_timeout(400)
        await pg.fill('#ptab-m3d textarea', 'a star'); await pg.click('#ptab-m3d button:has-text("Create from text")'); await pg.wait_for_timeout(600)
        await pg.click('#ptab-m3d button:has-text("Put on the page")'); await pg.wait_for_timeout(700)
        w3 = await (await pg.query_selector('.obj-m3d')).bounding_box()
        await pg.mouse.click(w3['x']+w3['width']/2, w3['y']+w3['height']/2+15, button='right'); await pg.wait_for_timeout(200)
        print('3D menu:', await pg.evaluate("[...document.querySelectorAll('.menu:not(.sub) > button')].map(b=>b.innerText.trim())")[:6] if False else await pg.evaluate("[...document.querySelectorAll('.menu:not(.sub) > button')].slice(0,6).map(b=>b.innerText.trim())"))
        await pg.hover('.menu button:has-text("Recording")'); await pg.wait_for_timeout(350)
        print('3D recording sub-menu:', await pg.evaluate("[...document.querySelectorAll('.menu.sub button')].map(b=>b.innerText.trim())"))
        await pg.keyboard.press('Escape'); await pg.mouse.click(1200, 780)
        await pg.click('#libraryBtn'); await pg.wait_for_timeout(600)
        print('library:', (await pg.inner_text('.modal')).replace('\n', ' | ')[:260])
        await pg.screenshot(path='t15.png')
        print('ERRORS', errs[:5])
        await b.close()
asyncio.run(main())
